<script src="https://cdn.jsdelivr.net/gh/studio-freight/lenis@1.0.23/bundled/lenis.min.js"></script>
<script>
   document.documentElement.style.height = "auto";
 
  const lenis = new Lenis({
 	smooth: true,
 	lerp: 0.1,
 	wheelMultiplier: 1,
 	infinite: false
   });
 
  // Sync Lenis with GSAP ScrollTrigger
   lenis.on('scroll', ScrollTrigger.update);
 
  gsap.ticker.add((time) => {
 	lenis.raf(time * 1000);
   });
 
  gsap.ticker.lagSmoothing(0);
 
  function raf(time) {
 	lenis.raf(time);
 	requestAnimationFrame(raf);
   }
   requestAnimationFrame(raf);
</script>

<!-- Page Smooth Scroll end -->

<!-- counter start-->

<script>

gsap.registerPlugin(ScrollTrigger);

const counters = document.querySelectorAll("[data-counter]");

counters.forEach((counter) => {

  // Original value
  const value = counter.getAttribute("data-counter");

  // Extract number
  const target = parseFloat(value);

  // Extract suffix
  const suffix = value.replace(/[0-9.]/g, "");

  // Counter object
  const obj = {
    val: 0
  };

  gsap.to(obj, {

    val: target,

    duration: 2,
    ease: "power1.out",

    scrollTrigger: {
      trigger: counter,
      start: "top 85%",
      toggleActions: "play none none none"
    },

    onUpdate: () => {

      counter.innerText =
        Math.floor(obj.val) + suffix;

    }

  });

});

</script>

<!------- counter end --------->



<!--Webflow custom code: banner-text-appear-->
<!--Webflow custom code: banner-text-appear-->

<script src="{{ asset('js/SplitText.min.js') }}"></script>

<script>
(function () {
  var targets = document.querySelectorAll("[banner-text-appear]");
  if (!targets.length) return;

  function revealInstantly() {
    targets.forEach(function (el) {
      el.style.visibility = "visible";
    });
  }

  if (typeof gsap === "undefined" || typeof SplitText === "undefined") {
    revealInstantly();
    return;
  }

  var prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (prefersReducedMotion) {
    revealInstantly();
    return;
  }

  gsap.registerPlugin(SplitText);

  var GAP = ">-0.3";
  var tl = gsap.timeline({
    defaults: { ease: "power3.out" },
    onComplete: revealInstantly
  });

  targets.forEach(function (el, i) {
    var split = new SplitText(el, { type: "lines", linesClass: "split-line" });
    gsap.set(el, { perspective: 2000, visibility: "visible" });
    tl.from(
      split.lines,
      {
        opacity: 0,
        yPercent: 100,
        rotationX: -30,
        transformOrigin: "50% 100% -20",
        duration: 0.7,
        stagger: 0.08,
        force3D: true
      },
      i === 0 ? 0 : GAP
    );
  });
})();
</script>





<!--
  Webflow custom code: banner appear animation
  Matches the panel's target field: [banner-appear]
-->
 


<script>
  window.Webflow ||= [];
  window.Webflow.push(() => {
    const targets = document.querySelectorAll("[banner-appear]");

    if (targets.length) {
      gsap.set(targets, { perspective: 2000 });

      gsap.fromTo(targets, 
        { opacity: 0, y: 30 }, 
        {
          opacity: 1,
          y: 0,
          duration: 0.6,
          delay: 0.5,
          ease: "power2.out",
          stagger: {
            each: 0.2,
            from: "start"
          }
        }
      );
    }
  });
</script>



